#include <bits/stdc++.h>
using namespace std;

const int N = 1010;
const int MOD = 1000000007;

int k, pa, pb;
int f[N][N];
long long probA, probB, invPb;

long long qpow(long long a, int b) {
    long long result = 1;
    while (b) {
        if (b & 1) result = result * a % MOD;
        a = a * a % MOD;
        b >>= 1;
    }
    return result;
}

int dfs(int i, int j) {
    if (i + j >= k)
        return ((i + j) + 1LL * pa * invPb) % MOD;

    int &result = f[i][j];
    if (result != -1) return result;

    result = (probA * dfs(i + 1, j) +
              probB * dfs(i, i + j)) % MOD;
    return result;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    cin >> k >> pa >> pb;
    memset(f, -1, sizeof(f));

    long long invSum = qpow((pa + pb) % MOD, MOD - 2);
    probA = pa * invSum % MOD;
    probB = pb * invSum % MOD;
    invPb = qpow(pb, MOD - 2);

    cout << dfs(1, 0) << '\n';
    return 0;
}

